import {forecastMonth} from './forecast.js?v=20261028-direct-v1';
const DOW=['일','월','화','수','목','금','토'];
export function renderForecast(f,{won,nf,esc,expanded=false}){
  if(f.status==='missing')return `<section class="card forecast-panel"><h3>월말 예상 매출</h3><p class="sub">${esc(f.reason)}</p></section>`;
  if(f.status==='closed')return `<section class="card forecast-panel"><h3>마감월 실적</h3><p>확보된 ${f.asof}까지의 매출 <b>${won(f.actual)}</b>입니다. 종료된 월에는 미래 예측을 표시하지 않습니다.</p></section>`;
  const percent=n=>(n*100).toFixed(1)+'%',trend=(f.trend>=1?'+':'')+((f.trend-1)*100).toFixed(1)+'%',weatherLabels={normal:'맑음·흐림',rain:'비·소나기',heat:'폭염',snow:'눈'};
  return `<section class="card forecast-panel"><div class="card-head"><div><h3>요일·추세로 보는 월말 예상</h3><div class="sub">${f.asof} 마감 입력 기준 · 페이히어 + 오터 + 네이버 총매출표 · ${f.stale?'최신 마감 자료 누락 · ':''}조건부 추정</div></div><span class="badge">${esc(f.model.label)}</span></div>
  <div class="forecast-equation"><div><span>확보된 실적</span><strong>${won(f.actual)}</strong></div><b>+</b><div><span>남은 ${f.horizon}일 예상</span><strong>${won(f.predicted)}</strong></div><b>=</b><div class="forecast-result"><span>월말 예상 매출</span><strong>${won(f.total)}</strong></div></div>
  <div class="forecast-metrics"><span>최근 추세 보정 <b>${trend}</b></span><span>${f.horizon}일 합계 검증 오차 <b>${f.wape===null?'검증 대기':percent(f.wape)}</b></span><span>단순 평균 방식 오차 <b>${f.baselineWape===null?'검증 대기':percent(f.baselineWape)}</b></span></div>
  <p class="forecast-range">과거 오차 참고 범위 <strong>${f.low===null?'검증 표본 부족 또는 날씨 시나리오 적용으로 범위 산출 보류':`${won(f.low)} ~ ${won(f.high)}`}</strong></p>
  <p class="sub">${esc(f.note)} 범위는 과거 오차의 10~90백분위에 따른 참고값이며 실제 매출을 보장하지 않습니다.${f.provisional?' 검증 표본이 부족하거나 검증되지 않은 조건이 있어 잠정 모델로 표시합니다.':''}</p>
  <details class="forecast-details" id="forecastDetails" ${expanded?'open':''}><summary>일자별 예상·요일 평균·검증 근거 보기</summary><h4>남은 날짜별 예상</h4><p class="sub">일별 예상 = 같은 요일의 최근 가중평균 × 추세 보정 × 근거가 확보된 날씨 보정. 날씨는 예보 연동 없이 직접 입력하는 가정입니다.</p><div class="table-wrap"><table><thead><tr><th>예상일</th><th class="num">요일 기준 매출</th><th>날씨 가정</th><th>날씨 적용</th><th class="num">예상 매출</th></tr></thead><tbody>${f.remaining.map(r=>`<tr><td>${r.date.slice(5).replace('-','.')} (${DOW[r.day]})</td><td class="num">${won(r.weekdayBase)}</td><td><select data-forecast-weather="${r.date}" aria-label="${r.date} 예상 날씨"><option value="">미확인</option>${Object.entries(weatherLabels).map(([k,v])=>`<option value="${k}" ${r.weather===k?'selected':''}>${v}</option>`).join('')}</select></td><td>${r.weatherApplied?((r.weatherFactor-1)*100).toFixed(1)+'%':r.weather==='normal'?'기준 조건 · 보정 없음':r.weather?'보정 표본 부족':'미반영'}</td><td class="num"><b>${won(r.sales)}</b></td></tr>`).join('')}</tbody></table></div>
  <h4>학습된 요일별 기준 매출</h4><div class="forecast-weekdays">${[1,2,3,4,5,6,0].map(d=>{const w=f.weekday[d];return `<div><span>${DOW[d]}</span><strong>${won(w.mean)}</strong><small>${w.count}일 표본</small></div>`}).join('')}</div>
  <h4>날씨 반영 상태</h4><p>최근 학습 기간의 날씨 기록 ${f.weatherKnown}일 · 정상 날씨 ${f.weatherNormal}일. ${Object.keys(f.weatherFactors).length?`보정 가능한 조건: ${Object.keys(f.weatherFactors).map(k=>weatherLabels[k]).join(', ')}. 입력한 날씨가 있는 미래 날짜에만 적용합니다.`:'정상 날씨와 비교 조건별 표본이 충분하지 않아 날씨 보정을 적용하지 않았습니다.'}</p><p class="sub">조건별 최소 8일, 최소 4개 요일, 3주 이상에 걸친 기록과 총 28일 이상의 날씨 기록이 필요합니다. 알 수 없는 날씨를 맑음으로 처리하지 않습니다. 추정된 연관성은 인과관계가 아니며, 날씨 적용 시나리오는 별도 성능 검증 전까지 참고 범위를 표시하지 않습니다.</p>
  <h4>과거 시점에서 검증한 결과</h4><div class="table-wrap"><table><thead><tr><th>후보 모델</th><th class="num">선정 구간 오차율</th><th class="num">검증 시점</th></tr></thead><tbody>${f.selectionScores.map(s=>`<tr><td>${esc(s.label)} ${s.id===f.model.id?'<span class="badge">선택</span>':''}</td><td class="num">${s.wape===null?'자료 부족':percent(s.wape)}</td><td class="num">${s.count}개</td></tr>`).join('')}</tbody></table></div><p class="sub">후보 선정과 별도의 최근 검증 ${f.validationCount}개 시점 (${f.evaluationStart||'—'} ~ ${f.evaluationEnd||'—'})에서, 당시까지의 데이터로 다음 ${f.horizon}일 합계를 예측했습니다. WAPE = 절대 오차 합 ÷ 실제 매출 합. 검증 대상 기간이 서로 겹칠 수 있어 독립적인 ${f.validationCount}개 실험을 뜻하지 않습니다.</p><p class="sub">최근 데이터에 더 높은 비중(28일 반감기)을 주고, 같은 요일의 극단값을 10~90백분위로 완화합니다. 추세는 최근 2주와 이전 4주의 요일 보정 매출을 비교해 변화폭의 절반만 반영하며 최대 ±20%로 제한합니다. 행사·공휴일 효과는 자동 추정하지 않습니다. 같은 기준의 전년 전 채널 총매출이 없어 연간 계절성은 반영하지 않습니다.</p></details></section>`;
}
export {forecastMonth};
